// FlexRay_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module FlexRay_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [3:0] c_cfg_spc,
  input logic [3:0] c_cfg_tss,
  input logic [9:0] c_cfg_slot,
  input logic [5:0] c_cfg_ap,
  input logic [5:0] c_cfg_nslots,
  input logic [9:0] c_cfg_nit,
  input logic [3:0] c_cfg_plen,
  input logic [5:0] c_cfg_my_slot,
  input logic  c_cfg_sync,
  input logic  c_cfg_cold,
  input logic  c_cfg_chan_b,
  input logic [7:0] c_cfg_corr,
  input logic [127:0] c_tx_data,
  input logic [127:0] c_rx_data,
  input logic [5:0] c_rx_id,
  input logic [5:0] c_rx_cycle,
  input logic [6:0] c_rx_len,
  input logic  c_rx_null,
  input logic  c_rx_sync,
  input logic  c_rx_startup,
  input logic  c_synced,
  input logic [5:0] c_cycle,
  input logic [5:0] c_slot,
  input logic  c_tx_valid,
  input logic  c_tx_ready,
  input logic  c_rx_valid,
  input logic  c_cycle_start,
  input logic  c_tx_done,
  input logic  c_err_coding,
  input logic  c_err_hcrc,
  input logic  c_err_fcrc,
  input logic  c_err_slot,
  input logic  c_err_sync
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 17;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:16];          // model of every stored word
  logic [10:0] m_set;                // interrupt bits set this clock
  logic m_state_TX;          // full / valid pulse / available
  logic m_state_RX;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_cycle_start) m_set[0] = 1'b1;
    if (c_tx_done) m_set[1] = 1'b1;
    if (c_err_coding) m_set[2] = 1'b1;
    if (c_err_hcrc) m_set[3] = 1'b1;
    if (c_err_fcrc) m_set[4] = 1'b1;
    if (c_err_slot) m_set[5] = 1'b1;
    if (c_err_sync) m_set[6] = 1'b1;
    if (m_state_TX && c_tx_ready) m_set[7] = 1'b1;
    if (m_wr && m_map && (m_idx == 7 || m_idx == 8 || m_idx == 9 || m_idx == 10) && m_state_TX) m_set[8] = 1'b1;
    if (c_rx_valid && !m_state_RX) m_set[9] = 1'b1;
    if (c_rx_valid && m_state_RX && (m_rd && m_map && m_idx == 15)) m_set[9] = 1'b1;
    if (c_rx_valid && m_state_RX && !(m_rd && m_map && m_idx == 15)) m_set[10] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h8307850;
      m_w[6] <= 32'h2000001E;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_state_TX <= 0;
      m_state_RX <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h7FF;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h3FFFFFFF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'h7FFFFFFF;
      if (m_wr && m_map && m_idx == 7 && !m_state_TX) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 8 && !m_state_TX) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 9 && !m_state_TX) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 10 && !m_state_TX) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 10 && !m_state_TX) m_state_TX <= 1;
      if (m_state_TX && c_tx_ready) m_state_TX <= 0;
      if (c_rx_valid && (!m_state_RX || (m_rd && m_map && m_idx == 15))) begin
        m_w[11] <= (32'(c_rx_data[31:0]) << 0);
        m_w[12] <= (32'(c_rx_data[63:32]) << 0);
        m_w[13] <= (32'(c_rx_data[95:64]) << 0);
        m_w[14] <= (32'(c_rx_data[127:96]) << 0);
        m_w[15] <= (32'(c_rx_id[5:0]) << 0) | (32'(c_rx_cycle[5:0]) << 6) | (32'(c_rx_len[6:0]) << 12) | (32'(c_rx_null) << 19) | (32'(c_rx_sync) << 20) | (32'(c_rx_startup) << 21);
        m_state_RX <= 1;
      end else if ((m_rd && m_map && m_idx == 15)) m_state_RX <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h46520200;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_RX, m_state_TX});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return m_w[11];
      12: return m_w[12];
      13: return m_w[13];
      14: return m_w[14];
      15: return m_w[15];
      16: return (32'(c_synced) << 0) | (32'(c_cycle) << 1) | (32'(c_slot) << 7);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][10:0] & m_w[2][10:0]))
  `SVA_INV(a_core_cfg_spc, c_cfg_spc == m_w[5][3:0])
  `SVA_INV(a_core_cfg_tss, c_cfg_tss == m_w[5][7:4])
  `SVA_INV(a_core_cfg_slot, c_cfg_slot == m_w[5][17:8])
  `SVA_INV(a_core_cfg_ap, c_cfg_ap == m_w[5][23:18])
  `SVA_INV(a_core_cfg_nslots, c_cfg_nslots == m_w[5][29:24])
  `SVA_INV(a_core_cfg_nit, c_cfg_nit == m_w[6][9:0])
  `SVA_INV(a_core_cfg_plen, c_cfg_plen == m_w[6][13:10])
  `SVA_INV(a_core_cfg_my_slot, c_cfg_my_slot == m_w[6][19:14])
  `SVA_INV(a_core_cfg_sync, c_cfg_sync == m_w[6][20:20])
  `SVA_INV(a_core_cfg_cold, c_cfg_cold == m_w[6][21:21])
  `SVA_INV(a_core_cfg_chan_b, c_cfg_chan_b == m_w[6][22:22])
  `SVA_INV(a_core_cfg_corr, c_cfg_corr == m_w[6][30:23])
  `SVA_INV(a_core_tx_data_31_0, c_tx_data[31:0] == m_w[7][31:0])
  `SVA_INV(a_core_tx_data_63_32, c_tx_data[63:32] == m_w[8][31:0])
  `SVA_INV(a_core_tx_data_95_64, c_tx_data[95:64] == m_w[9][31:0])
  `SVA_INV(a_core_tx_data_127_96, c_tx_data[127:96] == m_w[10][31:0])
  `SVA_INV(a_core_tx_valid, c_tx_valid == m_state_TX)
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cfg_spc == 4'h0 && c_cfg_tss == 4'h5 && c_cfg_slot == 10'h78 && c_cfg_ap == 6'hC && c_cfg_nslots == 6'h8 && c_cfg_nit == 10'h1E && c_cfg_plen == 4'h0 && c_cfg_my_slot == 6'h0 && c_cfg_sync == 1'h0 && c_cfg_cold == 1'h0 && c_cfg_chan_b == 1'h0 && c_cfg_corr == 8'h40 && c_tx_data[31:0] == 32'h0 && c_tx_data[63:32] == 32'h0 && c_tx_data[95:64] == 32'h0 && c_tx_data[127:96] == 32'h0 && !c_tx_valid)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CFG0, m_rd && m_map && m_idx == 5)
  `FC(wr_CFG0, m_wr && m_map && m_idx == 5)
  `FC(rd_CFG1, m_rd && m_map && m_idx == 6)
  `FC(wr_CFG1, m_wr && m_map && m_idx == 6)
  `FC(rd_TX0, m_rd && m_map && m_idx == 7)
  `FC(wr_TX0, m_wr && m_map && m_idx == 7)
  `FC(rd_TX1, m_rd && m_map && m_idx == 8)
  `FC(wr_TX1, m_wr && m_map && m_idx == 8)
  `FC(rd_TX2, m_rd && m_map && m_idx == 9)
  `FC(wr_TX2, m_wr && m_map && m_idx == 9)
  `FC(rd_TX3, m_rd && m_map && m_idx == 10)
  `FC(wr_TX3, m_wr && m_map && m_idx == 10)
  `FC(rd_RX0, m_rd && m_map && m_idx == 11)
  `FC(wr_RX0, m_wr && m_map && m_idx == 11)
  `FC(rd_RX1, m_rd && m_map && m_idx == 12)
  `FC(wr_RX1, m_wr && m_map && m_idx == 12)
  `FC(rd_RX2, m_rd && m_map && m_idx == 13)
  `FC(wr_RX2, m_wr && m_map && m_idx == 13)
  `FC(rd_RX3, m_rd && m_map && m_idx == 14)
  `FC(wr_RX3, m_wr && m_map && m_idx == 14)
  `FC(rd_RX4, m_rd && m_map && m_idx == 15)
  `FC(wr_RX4, m_wr && m_map && m_idx == 15)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 16)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 16)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_CYCLE_set, m_set[0])
  `FC(irq_CYCLE_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_CYCLE_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_CYCLE_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_SENT_set, m_set[1])
  `FC(irq_SENT_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_SENT_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_SENT_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_ERR_CODING_set, m_set[2])
  `FC(irq_ERR_CODING_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_ERR_CODING_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_ERR_CODING_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_ERR_HCRC_set, m_set[3])
  `FC(irq_ERR_HCRC_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_ERR_HCRC_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_ERR_HCRC_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_ERR_FCRC_set, m_set[4])
  `FC(irq_ERR_FCRC_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_ERR_FCRC_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_ERR_FCRC_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(irq_ERR_SLOT_set, m_set[5])
  `FC(irq_ERR_SLOT_cleared, m_w[1][5] && m_wr && m_map && m_idx == 1 && PWDATA[5] && PSTRB[0])
  `FC(irq_ERR_SLOT_masked, m_w[1][5] && !m_w[2][5])
  `FC(irq_ERR_SLOT_drives_pin, m_w[1][5] && m_w[2][5] && irq)
  `FC(irq_ERR_SYNC_set, m_set[6])
  `FC(irq_ERR_SYNC_cleared, m_w[1][6] && m_wr && m_map && m_idx == 1 && PWDATA[6] && PSTRB[0])
  `FC(irq_ERR_SYNC_masked, m_w[1][6] && !m_w[2][6])
  `FC(irq_ERR_SYNC_drives_pin, m_w[1][6] && m_w[2][6] && irq)
  `FC(irq_TX_DONE_set, m_set[7])
  `FC(irq_TX_DONE_cleared, m_w[1][7] && m_wr && m_map && m_idx == 1 && PWDATA[7] && PSTRB[0])
  `FC(irq_TX_DONE_masked, m_w[1][7] && !m_w[2][7])
  `FC(irq_TX_DONE_drives_pin, m_w[1][7] && m_w[2][7] && irq)
  `FC(irq_TX_OVF_set, m_set[8])
  `FC(irq_TX_OVF_cleared, m_w[1][8] && m_wr && m_map && m_idx == 1 && PWDATA[8] && PSTRB[1])
  `FC(irq_TX_OVF_masked, m_w[1][8] && !m_w[2][8])
  `FC(irq_TX_OVF_drives_pin, m_w[1][8] && m_w[2][8] && irq)
  `FC(irq_RX_AVAIL_set, m_set[9])
  `FC(irq_RX_AVAIL_cleared, m_w[1][9] && m_wr && m_map && m_idx == 1 && PWDATA[9] && PSTRB[1])
  `FC(irq_RX_AVAIL_masked, m_w[1][9] && !m_w[2][9])
  `FC(irq_RX_AVAIL_drives_pin, m_w[1][9] && m_w[2][9] && irq)
  `FC(irq_RX_OVF_set, m_set[10])
  `FC(irq_RX_OVF_cleared, m_w[1][10] && m_wr && m_map && m_idx == 1 && PWDATA[10] && PSTRB[1])
  `FC(irq_RX_OVF_masked, m_w[1][10] && !m_w[2][10])
  `FC(irq_RX_OVF_drives_pin, m_w[1][10] && m_w[2][10] && irq)
  `FC(TX_handshake, m_state_TX && c_tx_ready)
  `FC(TX_backpressure, m_state_TX && !c_tx_ready)
  `FC(TX_write_while_full, m_wr && m_map && m_idx == 10 && m_state_TX)
  `FC(RX_capture, c_rx_valid && !m_state_RX)
  `FC(RX_overflow, c_rx_valid && m_state_RX && !(m_rd && m_map && m_idx == 15))
  `FC(RX_pop, m_rd && m_map && m_idx == 15 && m_state_RX)
  `FC(RX_read_empty, m_rd && m_map && m_idx == 15 && !m_state_RX)
  `FC(RX_pop_and_capture, c_rx_valid && m_state_RX && m_rd && m_map && m_idx == 15)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind FlexRay_apb FlexRay_apb_sva u_apb_sva (.*);
